import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Pumpkin Market API","description":"","frontmatter":{"navigation":{"category":"Server operations"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/pumpkin-market-api.md"},"headers":[],"relativePath":"guides/pumpkin-market-api.md","filePath":"docs/pumpkin-market-api.md","lastUpdated":1791360073000}'),d={name:"guides/pumpkin-market-api.md"};function n(s,e,r,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="pumpkin-market-api" tabindex="-1">Pumpkin Market API <a class="header-anchor" href="#pumpkin-market-api" aria-label="Permalink to &quot;Pumpkin Market API&quot;">​</a></h1><p>This page records the Market API behavior used by this repository&#39;s publish action, the Market frontend, and PPM. It also records the API calls tested against the unpublished <code>TemporaryAPIExperiment</code> listing on 2026-10-07. No API token is stored here.</p><h2 id="listing-lookup" tabindex="-1">Listing lookup <a class="header-anchor" href="#listing-lookup" aria-label="Permalink to &quot;Listing lookup&quot;">​</a></h2><p>The public REST API is rooted at <code>https://market.pumpkinmc.org/api/v1/rest</code>.</p><table tabindex="0"><thead><tr><th>Request</th><th>Use</th></tr></thead><tbody><tr><td><code>GET /plugins/{id}</code></td><td>Resolve a numeric database ID or the listing&#39;s public ID to its listing metadata.</td></tr><tr><td><code>GET /plugins?q={name}&amp;limit={n}</code></td><td>Search listings by name. Confirm an exact name match; fail if it is ambiguous.</td></tr></tbody></table><p>The response includes the numeric <code>id</code>, <code>public_id</code>, <code>name</code>, <code>category</code>, <code>version</code> and basic listing information. PPM accepts public IDs, numeric IDs, exact names, and author/name input when resolving a plugin. This repository&#39;s publisher currently tries the direct endpoint first, then uses a bounded search and requires a case-insensitive exact name match. A name is not a valid direct path value: <code>GET /plugins/TemporaryAPIExperiment</code> returned 404, while the search endpoint found the listing.</p><p>The current publisher action accepts a plugin name or a numeric/public ID. For a name, it first tries that value as a direct path, accepts the result only if the returned listing name matches, and then falls back to bounded search with an exact-name check. The write endpoint itself requires the numeric database ID in its path.</p><p>The public API documentation lists read endpoints, including plugin lookup and download. It does not document the developer listing-write endpoint described below.</p><h2 id="updating-listing-metadata" tabindex="-1">Updating listing metadata <a class="header-anchor" href="#updating-listing-metadata" aria-label="Permalink to &quot;Updating listing metadata&quot;">​</a></h2><p>The Market frontend&#39;s Store Listing editor uses:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PUT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/plugins/{numeric-database-id}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;Market API token&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multipart/form-data</span></span></code></pre></div><p>The multipart form has a <code>metadata</code> part containing JSON. The frontend uses these fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Shape</th></tr></thead><tbody><tr><td><code>name</code></td><td>Listing display name</td></tr><tr><td><code>category</code></td><td>Market category</td></tr><tr><td><code>sourceLink</code></td><td>Optional source URL</td></tr><tr><td><code>youtubeVideoUrl</code></td><td>Optional video URL</td></tr><tr><td><code>keywords</code></td><td>Search keywords</td></tr><tr><td><code>translatedDescriptions</code></td><td>Object mapping locale codes to description strings; the frontend&#39;s default locale is <code>en-US</code></td></tr><tr><td><code>isEarlyAccess</code></td><td>Boolean</td></tr><tr><td><code>commands</code></td><td>Ordered array of command entries described below</td></tr></tbody></table><p>Each command entry may contain <code>id</code>, <code>name</code>, <code>aliases</code> (array), <code>permission</code>, <code>description</code> (locale map), and <code>display_order</code>. The frontend includes the database <code>id</code> for existing command rows when saving. It sends the complete command array in the listing form. <code>preview_image</code> is an optional separate multipart file field. Screenshot uploads and deletes use separate endpoints and are outside the metadata update flow.</p><p>The metadata-only update does not need a <code>wasm</code> part. Do not set the multipart <code>Content-Type</code> manually when using <code>fetch</code> and <code>FormData</code>; the runtime must add the boundary. The frontend uses cookie authentication and <code>X-Requested-With</code>; the API token used in this repository&#39;s publish action instead uses the Bearer header.</p><p>The current <code>publish-to-pumpkin-market</code> action uses the same <code>PUT</code> URL with a <code>wasm</code> file and a different <code>metadata</code> object: <code>version</code>, <code>track</code>, and <code>releaseNotes</code>. Its README documents the token scopes used for version uploads. The test below proves that the supplied token could update the test listing, but does not isolate the minimum scope required for metadata changes. The frontend also surfaces a 2FA requirement for listing saves and version publishing. Whether API-token writes require the account to have 2FA enabled has not been isolated.</p><h2 id="partial-and-full-listing-updates" tabindex="-1">Partial and full listing updates <a class="header-anchor" href="#partial-and-full-listing-updates" aria-label="Permalink to &quot;Partial and full listing updates&quot;">​</a></h2><p>There is no separate <code>PATCH</code> method in the observed frontend flow: both partial metadata edits and full listing saves use <code>PUT /api/plugins/{id}</code>. The difference is the set of keys in the JSON <code>metadata</code> part.</p><p>The API test sent a partial object containing <code>translatedDescriptions</code> and <code>commands</code>, then read the listing through the public REST endpoint. The listing&#39;s existing <code>name</code> and <code>category</code> remained unchanged. A full listing object containing <code>name</code>, <code>category</code>, <code>sourceLink</code>, <code>youtubeVideoUrl</code>, <code>keywords</code>, <code>translatedDescriptions</code>, <code>isEarlyAccess</code>, and <code>commands</code> was also accepted. A later partial update left the full update&#39;s category unchanged. These observations support using the same metadata-only <code>PUT</code> for both patch-style edits and complete listing updates.</p><p>Command-row reconciliation is not fully verified. The write endpoint returned success for command arrays, but the available public REST response does not include description or command rows. A Bearer-authenticated <code>GET /api/plugins/{id}</code> for the unpublished draft returned <code>This plugin is currently offline / draft.</code> The frontend preserves command IDs, but the backend behavior for omitted IDs, omitted commands, and deletion has not been confirmed.</p><h2 id="tested-behavior" tabindex="-1">Tested behavior <a class="header-anchor" href="#tested-behavior" aria-label="Permalink to &quot;Tested behavior&quot;">​</a></h2><p>All writes below targeted only the unpublished <code>TemporaryAPIExperiment</code> listing. No WASM binary was uploaded, and no other listing was accessed for mutation.</p><ul><li>Public detail lookup by numeric database ID and public ID both returned the same listing and numeric database ID.</li><li>Direct lookup by name returned 404; a bounded name search returned the exact listing.</li><li>A Bearer-authenticated metadata-only <code>PUT</code> containing a localized description and one command returned HTTP 200 with <code>{&quot;id&quot;:…, &quot;status&quot;:&quot;updated&quot;, &quot;version&quot;:&quot;&quot;}</code>.</li><li>A full listing metadata <code>PUT</code> also returned HTTP 200. The public REST readback showed the updated category and retained the listing name.</li><li>A subsequent partial metadata <code>PUT</code> returned HTTP 200 and left the category unchanged.</li><li>The listing remained offline/draft, and no binary version was published. Its public <code>version</code> changed from <code>null</code> to an empty string after metadata-only writes. Because the fixture has no published version, this does not establish whether a metadata-only write preserves version data on an already-published listing.</li><li>The test fixture is left unpublished with category <code>Other</code> and the API probe description/command metadata.</li></ul><p>The request shape and command fields are confirmed by the frontend code. The API observations here do not establish command persistence, command deletion semantics, or whether metadata-only writes preserve version and track data on an already-published listing.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://github.com/Pumpkin-MC/Market-Frontend/blob/master/src/api.ts" target="_blank" rel="noreferrer">Market frontend API client</a></li><li><a href="https://github.com/Pumpkin-MC/Market-Frontend/blob/master/src/pages/dashboard/plugin/StoreListing.tsx" target="_blank" rel="noreferrer">Market frontend Store Listing editor</a></li><li><a href="https://github.com/Pumpkin-MC/Market-Frontend/blob/master/src/types/plugin.ts" target="_blank" rel="noreferrer">Market frontend plugin types</a></li><li><a href="https://github.com/Pumpkin-MC/ppm/blob/main/src/market/client.rs" target="_blank" rel="noreferrer">PPM market API client</a></li><li><a href="https://github.com/Pumpkin-MC/ppm/blob/main/src/market/models.rs" target="_blank" rel="noreferrer">PPM market response models</a></li><li><a href="https://market.pumpkinmc.org/api/docs/" target="_blank" rel="noreferrer">Pumpkin Market API docs</a></li><li><a href="./../actions/publish-to-pumpkin-market/README">This repository&#39;s Market publisher</a></li><li><a href="./ci-and-releases#publishing-to-marketpumpkinmcorg">CI and release workflow</a></li></ul>`,26)])])}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
